            TerraformStep(
                order: 2,
                title: "Put mass between yourself and the sky",
                mechanism: "What stops a cosmic ray is grams of material per square centimetre in the way, and broadly not what the grams are made of, which means the regolith underfoot is the shielding and it is free. Roughly 100 g per square centimetre brings a galactic-cosmic-ray dose down towards terrestrial; past that, secondary particles produced in the shield start to offset what the shield stops, so more depth buys progressively less. Lava tubes do this for nothing: the Moon and Mars both have intact ones hundreds of metres across, already roofed by tens of metres of basalt.",
                quantities: [
                    Quantity(label: "Dose at the surface", value: 0.0365, unit: "Sv/yr"),
                    Quantity(label: "Times Earth background", value: 15.208333333333334, unit: "x"),
                    Quantity(label: "Shielding needed", value: 100.0, unit: "g/cm2"),
                    Quantity(label: "Depth of regolith that is", value: 0.6666666666666666, unit: "m"),
                    Quantity(label: "Mass over a 100 m dome", value: 7853981.633974482, unit: "kg")
                ],
                timescale: "immediate with local material",
                maturity: .engineeringExtrapolation,
                source: "Hassler et al. 2014, Science 343, 1244797; Simonsen & Nealy 1991, NASA TP-3079"
            ),
            TerraformStep(
                order: 3,
                title: "Mine the volatiles out of the cold traps",
                mechanism: "An airless body with a small axial tilt has craters at its poles whose floors have not seen sunlight in billions of years, sitting at 40 K or below. Anything volatile that ever arrived is still there. Both the Moon and Mercury have confirmed water ice in exactly these places, Mercury's by radar and neutron spectroscopy despite a dayside hot enough to melt lead a few hundred kilometres away. That water is hydrogen, oxygen, propellant, radiation shielding and drinking water, and it is why the poles rather than the equator are where a base goes.",
                quantities: [
                    Quantity(label: "Obliquity", value: 0.0, unit: "deg"),
                    Quantity(label: "Solar day", value: 16.753548798032305, unit: "days"),
                    Quantity(label: "Sunlight here", value: 50.283147369342565, unit: "W/m2"),
                    Quantity(label: "Relative to Earth", value: 0.03694121817367084, unit: "x")
                ],
                timescale: "first decade of any serious presence",
                maturity: .demonstrated,
                source: "Lawrence et al. 2013, Science 339, 292 (MESSENGER); Colaprete et al. 2010, Science 330, 463 (LCROSS)"
            ),
            TerraformStep(
                order: 4,
                title: "If you want open air, roof the planet rather than wrapping it",
                mechanism: "Paraterraforming, the worldhouse: rather than give the body an atmosphere it cannot hold, build a transparent canopy over the surface and pressurise underneath it. The structural requirement inverts the usual intuition. The roof is not holding pressure down, it is holding it in against the vacuum above, so what it needs is tensile strength and mass, and the mass needed per square metre is exactly the mass of atmosphere it replaces. Low gravity, which is a problem everywhere else on this list, is here the thing that makes it cheap. It also scales: it works at one hectare and at one hemisphere, and there is no threshold to cross before any of it is useful.",
                quantities: [
                    Quantity(label: "Whole-body roof area", value: 73004909268141.22, unit: "m2"),
