                quantities: [
                    Quantity(label: "Measured surface", value: 94.0, unit: "K"),
                    Quantity(label: "Sunlight alone", value: 83.45131803404296, unit: "K"),
                    Quantity(label: "Greenhouse effect now", value: 10.548681965957044, unit: "K", note: "Earth's is 33 K"),
