                quantities: [
                    Quantity(label: "Surface temperature now", value: 94.0, unit: "K"),
                    Quantity(label: "Warming required", value: 194.0, unit: "K"),
                    Quantity(label: "Heat to warm the atmosphere alone", value: 1.820689251514397e+24, unit: "J"),
                    Quantity(label: "Sunlight the whole body intercepts", value: 311702704185260.8, unit: "W"),
                    Quantity(label: "Years of all incident sunlight", value: 185.0935526364772, unit: "years", note: "the atmosphere only; the crust is the same again many times over")
                ],
                timescale: "millennia",
                maturity: .speculative,
                source: "Lorenz, Lunine & McKay 1997, GRL 24, 2905; Fogg 1995, ch. 12"
